/* Table sorting, data freshness and region links. */
function sourceDate(){
  const match=String(state.meta?.source||'').match(/(\d{2})\.(\d{2})\.(\d{4})/);
  return match?`${match[1]}.${match[2]}.${match[3]}`:'';
}

function refreshFreshness(){
  const el=$('#dataFreshness');if(!el)return;
  const date=sourceDate();
  el.innerHTML=`<span class="freshness-dot"></span><span>Данные: <strong>${esc(shortPeriod(state.meta?.period)||state.meta?.period||'—')}</strong>${date?` · отчет от ${date}`:''}</span>`;
}

function tableValue(cell){
  const text=(cell?.innerText||'').replace(/\s+/g,' ').trim();
  if(!text||text==='—')return {empty:true,text:''};
  const normalized=text.replace(/\s/g,'').replace(',','.').replace(/[^0-9+\-.]/g,'');
  const value=Number(normalized);
  return Number.isFinite(value)&&/[0-9]/.test(text)?{number:value,text}:{text:text.toLocaleLowerCase('ru')};
}

function makeTablesSortable(){
  $$('.data-table').forEach(table=>{
    if(table.dataset.sortReady)return;table.dataset.sortReady='1';
    [...(table.tHead?.rows?.[0]?.cells||[])].forEach((th,index)=>{
      th.classList.add('sortable-th');th.title='Нажмите для сортировки';th.tabIndex=0;
      const sort=()=>{
        const body=table.tBodies[0];if(!body)return;
        const next=th.dataset.order==='asc'?'desc':'asc';
        [...th.parentElement.cells].forEach(x=>{delete x.dataset.order;x.removeAttribute('aria-sort')});
        th.dataset.order=next;th.setAttribute('aria-sort',next==='asc'?'ascending':'descending');
        const rows=[...body.rows];
        rows.sort((a,b)=>{
          const av=tableValue(a.cells[index]),bv=tableValue(b.cells[index]);
          if(av.empty)return 1;if(bv.empty)return -1;
          const result=av.number!=null&&bv.number!=null?av.number-bv.number:String(av.text).localeCompare(String(bv.text),'ru',{numeric:true});
          return next==='asc'?result:-result;
        });
        rows.forEach(row=>body.appendChild(row));
      };
      th.addEventListener('click',sort);th.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();sort()}});
    });
  });
}

